WITH deduped AS (SELECT id, carrier, shipped_date, delivered_date, status FROM shipments QUALIFY RANK() OVER (PARTITION BY carrier ORDER BY cost NULLS LAST) = 1) SELECT carrier, SORT_ARRAY(COLLECT_SET(carrier)) AS carrier_list, SIZE(COLLECT_SET(status)) AS num_status, SORT_ARRAY(COLLECT_SET(carrier)) AS carrier_list_2, COUNT_IF(status = 'LOST') AS lost_events, COUNT(*) FILTER (WHERE status = 'LOST') AS lost_rows, SIZE(COLLECT_SET(status)) AS num_status_2 FROM deduped GROUP BY carrier
